.aero-app-shell {
 isolation: isolate;
 background: var(--background);
 position: fixed;
 inset: 0;
 overflow: hidden;
}

.aero-user-background {
 z-index: -3;
 opacity: .18;
 pointer-events: none;
 background-position: center;
 background-size: cover;
 position: absolute;
 inset: 0;
}

.aero-app-shell:before {
 z-index: -2;
 content: "";
 background: radial-gradient(ellipse at 12% 8%, var(--primary), transparent 38%), radial-gradient(ellipse at 88% 72%, var(--primary), transparent 40%), radial-gradient(ellipse at 50% 100%, var(--primary), transparent 50%), linear-gradient(140deg, var(--background) 0%, var(--card) 42%, var(--background) 100%);
 position: absolute;
 inset: 0;
}

@supports (color: color-mix(in lab, red, red)) {
 .aero-app-shell:before {
 background: radial-gradient(ellipse at 12% 8%, color-mix(in oklab, var(--primary) 30%, transparent), transparent 38%), radial-gradient(ellipse at 88% 72%, color-mix(in oklab, var(--primary) 22%, transparent), transparent 40%), radial-gradient(ellipse at 50% 100%, color-mix(in oklab, var(--primary) 16%, transparent), transparent 50%), linear-gradient(140deg, var(--background) 0%, var(--card) 42%, var(--background) 100%);
 }
}

.aero-app-shell:before {
 pointer-events: none;
}

.aero-app-shell:after {
 z-index: -1;
 content: "";
 opacity: .5;
 background: repeating-linear-gradient(115deg, transparent 0 110px, var(--glow) 130px 133px, transparent 160px 280px);
 position: absolute;
 inset: -30%;
}

@supports (color: color-mix(in lab, red, red)) {
 .aero-app-shell:after {
 background: repeating-linear-gradient(115deg, transparent 0 110px, color-mix(in oklab, var(--glow) 14%, transparent) 130px 133px, transparent 160px 280px);
 }
}

.aero-app-shell:after {
 pointer-events: none;
 animation: 24s linear infinite aero-bg-drift;
}

.aero-bg-glow {
 z-index: -1;
 filter: blur(80px);
 opacity: .22;
 pointer-events: none;
 border-radius: 9999px;
 animation: 16s ease-in-out infinite alternate aero-bg-float;
 position: absolute;
}

.aero-bg-glow-one {
 background: var(--primary);
 width: 300px;
 height: 300px;
 top: 10%;
 left: 6%;
}

.aero-bg-glow-two {
 background: var(--glow);
 width: 340px;
 height: 340px;
 animation-delay: -6s;
 bottom: 6%;
 right: 8%;
}

.aero-splash {
 background: var(--background);
 transition: opacity .5s;
}

@keyframes aero-bg-drift {
 from {
 transform: translate3d(-7%, -4%, 0) rotate(0);
 }

 to {
 transform: translate3d(7%, 4%, 0) rotate(2.5deg);
 }
}

@keyframes aero-bg-float {
 from {
 transform: translate3d(-20px, 14px, 0) scale(.9);
 }

 to {
 transform: translate3d(24px, -18px, 0) scale(1.1);
 }
}

@keyframes aero-fade-in {
 from {
 opacity: 0;
 transform: translateY(8px);
 }

 to {
 opacity: 1;
 transform: translateY(0);
 }
}

[data-motion="off"] .aero-app-shell:after, [data-motion="off"] .aero-bg-glow {
 opacity: .04;
 animation: none;
}

@media (prefers-reduced-motion: reduce) {
 .aero-app-shell:after, .aero-bg-glow {
 animation: none;
 }
}

html[data-cursor], html[data-cursor] body {
