}

[data-layout="dock"] .aero-mini-player {
 bottom: 5.5rem;
}

.aero-fx-piece {
 will-change: transform, opacity;
 -webkit-user-select: none;
 user-select: none;
 line-height: 1;
 animation-timing-function: linear;
 animation-iteration-count: infinite;
 position: absolute;
}

.aero-fx-fall {
 color: oklch(97% .02 240);
 text-shadow: 0 0 6px oklch(90% .05 240 / .7);
 animation-name: aero-fx-fall;
 top: -40px !important;
}

.aero-fx-rise {
 color: oklch(92% .06 220 / .8);
 animation-name: aero-fx-rise;
 bottom: -40px;
 top: auto !important;
}

.aero-fx-swim, .aero-fx-fly {
 animation-name: aero-fx-swim;
 left: -60px !important;
}

.aero-fx-fly {
 animation-name: aero-fx-fly;
 top: calc(var(--fx-sway) * .4 + 22%) !important;
}

.aero-fx-twinkle {
 color: oklch(95% .05 90);
 text-shadow: 0 0 8px oklch(95% .08 90 / .8);
 animation-name: aero-fx-twinkle;
 animation-timing-function: ease-in-out;
}

.aero-fx-burst {
 background: radial-gradient(circle, transparent 30%, hsl(var(--fx-hue) 95% 65%) 31% 34%, transparent 35% 48%, hsl(calc(var(--fx-hue) + 40) 95% 70%) 49% 52%, transparent 53%);
 -webkit-mask: repeating-conic-gradient(#000 0 6deg, transparent 6deg 18deg);
 -webkit-mask: repeating-conic-gradient(#000 0 6deg, transparent 6deg 18deg);
 mask: repeating-conic-gradient(#000 0 6deg, transparent 6deg 18deg);
 border-radius: 9999px;
 animation-name: aero-fx-burst;
 animation-timing-function: ease-out;
 top: calc(var(--fx-sway) * .2 + 22%) !important;
}

.aero-fx-bob {
 animation: 3.5s ease-in-out infinite alternate aero-fx-bob;
}

.aero-fx-sway {
 transform-origin: bottom;
 animation: 4s ease-in-out infinite alternate aero-fx-sway;
}

.aero-fx-spin {
 animation: 40s linear infinite aero-fx-spin;
}

.aero-fx-shooting {
 opacity: 0;
 background: linear-gradient(90deg, oklch(100% 0 0 / 0), oklch(100% 0 0 / .95));
 border-radius: 9999px;
 width: 120px;
 height: 2px;
 animation: 10.5s ease-out infinite aero-fx-shoot;
 position: absolute;
 transform: rotate(-25deg);
}

.aero-fx-lights {
 background: radial-gradient(120% 18px at 50% -6px, #0000 60%, oklch(35% .05 150 / .9) 62% 66%, #0000 68%) 0 0 / 46px 22px repeat-x;
 height: 22px;
}

.aero-fx-bulb {
 border-radius: 50% / 40% 40% 60% 60%;
 width: 9px;
 height: 13px;
 margin-top: 9px;
 animation: 1.6s ease-in-out infinite alternate aero-fx-glow;
}

.aero-fx-bulb-0 {
