 background: oklch(85% .17 90);
}

.aero-fx-bulb-3 {
 color: oklch(68% .17 250);
 background: oklch(68% .17 250);
}

.aero-fx-tint {
 opacity: .55;
}

[data-special="christmas"] .aero-fx-tint {
 background: radial-gradient(60% 40% at 0 100%, oklch(55% .2 25 / .18), #0000), radial-gradient(60% 40% at 100% 100%, oklch(55% .17 150 / .18), #0000);
}

[data-special="halloween"] .aero-fx-tint {
 background: radial-gradient(70% 50% at 50% 110%, oklch(60% .2 50 / .22), #0000), radial-gradient(60% 50% at 100% 0, oklch(45% .22 300 / .25), #0000);
}

[data-special="valentine"] .aero-fx-tint {
 background: radial-gradient(70% 50% at 50% 110%, oklch(65% .22 0 / .22), #0000);
}

[data-special="spring"] .aero-fx-tint {
 background: radial-gradient(60% 40% at 0 0, oklch(85% .1 350 / .18), #0000), radial-gradient(60% 40% at 100% 100%, oklch(75% .17 140 / .16), #0000);
}

[data-special="space"] .aero-fx-tint {
 background: radial-gradient(50% 40% at 80% 20%, oklch(45% .2 290 / .25), #0000), radial-gradient(50% 40% at 10% 80%, oklch(45% .15 230 / .2), #0000);
}

[data-special="ocean"] .aero-fx-tint {
 background: linear-gradient(#0000 40%, oklch(45% .12 210 / .25));
}

[data-special="autumn"] .aero-fx-tint {
 background: radial-gradient(70% 50% at 50% 110%, oklch(62% .17 55 / .22), #0000);
}

[data-special="newyear"] .aero-fx-tint {
 background: radial-gradient(60% 40% at 50% 0, oklch(80% .14 85 / .14), #0000);
}

[data-special="summer"] .aero-fx-tint {
 background: radial-gradient(50% 40% at 100% 0, oklch(88% .17 90 / .22), #0000), linear-gradient(#0000 70%, oklch(80% .12 80 / .14));
}

@keyframes aero-fx-fall {
 from {
 transform: translate3d(0, 0, 0) rotate(0);
 }

 50% {
 transform: translate3d(var(--fx-sway), 55vh, 0) rotate(180deg);
 }

 to {
 transform: translate3d(0, 110vh, 0) rotate(360deg);
 }
}

@keyframes aero-fx-rise {
 from {
 opacity: 0;
 transform: translate3d(0, 0, 0);
 }

 10% {
 opacity: 1;
 }

 50% {
 transform: translate3d(var(--fx-sway), -55vh, 0);
 }

 90% {
 opacity: 1;
 }

 to {
 opacity: 0;
 transform: translate3d(0, -110vh, 0);
 }
}

@keyframes aero-fx-swim {
 from {
 transform: translate3d(0, 0, 0);
 }

 50% {
 transform: translate3d(55vw, calc(var(--fx-sway) * .3), 0);
 }

 to {
 transform: translate3d(calc(100vw + 120px), 0, 0);
 }
}

@keyframes aero-fx-fly {
 0% {
 transform: translate3d(0, 0, 0);
 }

 25% {
 transform: translate3d(25vw, -30px, 0);
 }

 50% {
 transform: translate3d(55vw, 20px, 0);
 }

 75% {
 transform: translate3d(80vw, -24px, 0);
 }

 100% {
 transform: translate3d(calc(100vw + 120px), 0, 0);
 }
}

@keyframes aero-fx-twinkle {
 0%, 100% {
 opacity: .15;
 transform: scale(.7);
 }

 50% {
 opacity: 1;
 transform: scale(1.15);
 }
}

@keyframes aero-fx-burst {
 0% {
 opacity: 0;
 transform: scale(.1);
 }

 15% {
 opacity: 1;
 }

 70% {
 opacity: .8;
 }

 100% {
 opacity: 0;
 transform: scale(1);
 }
}

@keyframes aero-fx-bob {
 from {
 transform: translateY(0);
 }

 to {
 transform: translateY(-10px);
 }
}

@keyframes aero-fx-sway {
 from {
 transform: rotate(-5deg);
 }

 to {
 transform: rotate(5deg);
 }
}

@keyframes aero-fx-spin {
 to {
 transform: rotate(360deg);
 }
}

@keyframes aero-fx-shoot {
 0% {
 opacity: 0;
 transform: translate3d(0, 0, 0) rotate(-25deg);
 }

 2% {
 opacity: 1;
 }

 9% {
 opacity: 0;
 transform: translate3d(-260px, 120px, 0) rotate(-25deg);
 }

 100% {
 opacity: 0;
 transform: translate3d(-260px, 120px, 0) rotate(-25deg);
 }
}

@keyframes aero-fx-glow {
 from {
 opacity: .45;
 box-shadow: 0 0 2px;
 }

 to {
 opacity: 1;
 box-shadow: 0 0 10px 2px;
 }
}

[data-motion="off"] :is(.aero-fx-fall, .aero-fx-rise, .aero-fx-swim, .aero-fx-fly, .aero-fx-burst, .aero-fx-shooting) {
 display: none;
}

[data-motion="off"] :is(.aero-fx-twinkle, .aero-fx-bob, .aero-fx-sway, .aero-fx-spin, .aero-fx-bulb) {
 animation: none;
}

@media (prefers-reduced-motion: reduce) {
 :is(.aero-fx-fall, .aero-fx-rise, .aero-fx-swim, .aero-fx-fly, .aero-fx-burst, .aero-fx-shooting) {
 display: none;
 }

 :is(.aero-fx-twinkle, .aero-fx-bob, .aero-fx-sway, .aero-fx-spin, .aero-fx-bulb) {
 animation: none;
 }
}

.home-game-track {
 transform: translateX(0);
}

.home-game-track-sliding {
 transition: transform 1.4s cubic-bezier(.65, 0, .35, 1);
 transform: translateX(calc(-50% - .375rem));
}

.home-game-tile {
 width: calc(50% - .375rem);
}

@media (width >= 40rem) {
 .home-game-track-sliding {
 transform: translateX(calc(-33.3333% - .25rem));
 }

 .home-game-tile {
 width: calc(33.3333% - .5rem);
 }
}

@media (width >= 64rem) {
 .home-game-track-sliding {
 transform: translateX(calc(-16.6667% - .125rem));
 }

 .home-game-tile {
 width: calc(16.6667% - .625rem);
 }
}

.game-rail {
 overflow: hidden;
}

.game-rail-track {
 --rail-gap: .75rem;
 --rail-shift: calc(-1 * (100% + .75rem) / 3);
 --tile-w: calc((100% - 1.5rem) / 3);
 gap: var(--rail-gap);
 width: 100%;
 display: flex;
}

.game-rail-tile {
 width: var(--tile-w);
 flex: none;
}

.game-rail-fwd {
 transform: translateX(0);
}

.game-rail-rev {
 transform: translateX(var(--rail-shift));
}

.game-rail-track.is-sliding {
 transition: transform 1.2s cubic-bezier(.65, 0, .35, 1);
}

.game-rail-fwd.is-sliding {
 transform: translateX(var(--rail-shift));
}

.game-rail-rev.is-sliding {
 transform: translateX(0);
}

@media (width >= 40rem) {
 .game-rail-track {
 --rail-shift: calc(-1 * (100% + .75rem) / 4);
 --tile-w: calc((100% - 2.25rem) / 4);
 }
}

@media (width >= 64rem) {
 .game-rail-track {
 --rail-shift: calc(-1 * (100% + .75rem) / 7);
 --tile-w: calc((100% - 4.5rem) / 7);
 }
}

.potato-marquee-wrap {
 overflow: hidden;
 -webkit-mask-image: linear-gradient(90deg, #0000, #000 5% 95%, #0000);
 mask-image: linear-gradient(90deg, #0000, #000 5% 95%, #0000);
}

.potato-marquee {
 width: max-content;
 animation: linear infinite potato-marquee;
 display: flex;
}

.potato-marquee:hover {
 animation-play-state: paused;
}

.settings-no-results {
 display: none;
}

.settings-no-results:not([hidden]):has( ~ div [data-settings-section]):not(:has( ~ div [data-settings-section]:not([hidden]))) {
 display: block;
}

[hidden] {
 display: none !important;
}

@keyframes potato-marquee {
 from {
 transform: translateX(0);
 }

 to {
 transform: translateX(-50%);
 }
}

@media (prefers-reduced-motion: reduce) {
 .potato-marquee {
 animation: none;
 }

 .potato-marquee-wrap {
 overflow-x: auto;
 }
}

:root {
 --page-bg: oklch(98.5% .004 80);
 --page-fg: oklch(22% .01 60);
 --page-muted: oklch(48% .012 60);
 --page-link: oklch(45% .16 255);
 --page-line: oklch(90% .006 80);
}

.search-page {
 background: var(--page-bg);
 color: var(--page-fg);
}

.search-page-header {
 background: var(--page-bg);
}

@supports (color: color-mix(in lab, red, red)) {
 .search-page-header {
 background: color-mix(in oklab, var(--page-bg) 88%, transparent);
 }
}

.search-page-header {
 -webkit-backdrop-filter: blur(12px);
 backdrop-filter: blur(12px);
 border-color: var(--page-line);
}

.search-page-input {
 background: var(--page-bg);
 border-color: var(--page-line);
 box-shadow: 0 1px 6px oklch(0% 0 0 / .08);
}

.search-page-link {
 color: var(--page-link);
}

.search-page-muted {
 color: var(--page-muted);
}

:root {
 --nitro-gold: oklch(86% .15 85);
 --nitro-gold-2: oklch(70% .16 60);
 --nitro-fire: oklch(72% .21 45);
 --nitro-fire-2: oklch(62% .24 25);
 --nitro-fire-3: oklch(90% .16 95);
 --nitro-ice: oklch(90% .08 220);
 --nitro-ice-2: oklch(72% .14 235);
 --nitro-pink: oklch(80% .13 350);
 --nitro-pink-2: oklch(68% .2 0);
 --nitro-violet: oklch(66% .22 295);
 --nitro-cyan: oklch(82% .15 200);
 --nitro-lime: oklch(86% .2 140);
 --nitro-white: oklch(98% 0 0);
}

.nitro-wrap {
 isolation: isolate;
 flex-shrink: 0;
 place-items: center;
 display: inline-grid;
 position: relative;
}

.nd {
 pointer-events: none;
 z-index: 2;
 position: absolute;
 inset: -14%;
}

.nd-ring {
 border-radius: 9999px;
 position: absolute;
 inset: 0;
 -webkit-mask: radial-gradient(farthest-side, #0000 87%, #000 88% 99%, #0000);
 mask: radial-gradient(farthest-side, #0000 87%, #000 88% 99%, #0000);
}

.nd i {
 display: block;
 position: absolute;
}

@keyframes nd-spin {
 to {
 transform: rotate(1turn);
 }
}

@keyframes nd-breathe {
 50% {
 opacity: .75;
 transform: scale(1.06);
 }
}

@keyframes nd-twinkle {
 0%, 100% {
 opacity: 0;
 transform: scale(.2) rotate(0);
 }

 50% {
 opacity: 1;
 transform: scale(1) rotate(90deg);
 }
}

@keyframes nd-ripple {
 from {
 opacity: .9;
 transform: scale(.85);
 }

 to {
 opacity: 0;
 transform: scale(1.25);
 }
}

.nd-glow .nd-ring {
 background: conic-gradient(from 0deg, var(--primary), var(--accent), var(--primary));
 filter: drop-shadow(0 0 6px var(--primary));
 animation: 6s linear infinite nd-spin;
}

.nd-glow:after {
 content: "";
 box-shadow: 0 0 18px 2px var(--primary);
 border-radius: 9999px;
 position: absolute;
 inset: 6%;
}

@supports (color: color-mix(in lab, red, red)) {
 .nd-glow:after {
 box-shadow: 0 0 18px 2px color-mix(in oklab, var(--primary) 60%, transparent);
 }
}

.nd-glow:after {
 animation: 3s ease-in-out infinite nd-breathe;
}

.nd-pulse .nd-ring {
 background: var(--nitro-pink-2);
}

.nd-pulse:before, .nd-pulse:after {
 content: "";
 border: 2px solid var(--nitro-pink);
 border-radius: 9999px;
 animation: 1.6s ease-out infinite nd-ripple;
 position: absolute;
 inset: 4%;
}

.nd-pulse:after {
 animation-delay: .8s;
}

.nd-sparkle .nd-ring {
 background: conic-gradient(var(--nitro-gold), var(--nitro-white), var(--nitro-gold-2), var(--nitro-white), var(--nitro-gold));
 animation: 8s linear infinite nd-spin;
}

.nd-sparkle i {
 width: 26%;
 height: 26%;
 left: calc(50% + 50% * cos(calc(var(--i) * 72deg)) - 13%);
 top: calc(50% + 50% * sin(calc(var(--i) * 72deg)) - 13%);
 background: var(--nitro-white);
 clip-path: polygon(50% 0, 61% 39%, 100% 50%, 61% 61%, 50% 100%, 39% 61%, 0 50%, 39% 39%);
 filter: drop-shadow(0 0 4px var(--nitro-gold));
 animation: 2.2s ease-in-out infinite nd-twinkle;
 animation-delay: calc(var(--i) * -.44s);
}

.nd-fire .nd-ring {
 background: conic-gradient(var(--nitro-fire-2), var(--nitro-fire), var(--nitro-fire-3), var(--nitro-fire), var(--nitro-fire-2));
 filter: drop-shadow(0 0 6px var(--nitro-fire));
 animation: 3s linear infinite nd-spin;
}

.nd-fire i {
 bottom: 40%;
 left: calc(8% + var(--i) * 12%);
 background: radial-gradient(ellipse at 50% 80%, var(--nitro-fire-3), var(--nitro-fire) 45%, transparent 72%);
 filter: blur(.5px);
 transform-origin: 50% 100%;
 width: 16%;
 height: 30%;
 animation: 1.1s ease-in-out infinite alternate nd-flame;
 animation-delay: calc(var(--i) * -.17s);
 border-radius: 50% 50% 30% 30% / 70% 70% 30% 30%;
 top: -14%;
}

@keyframes nd-flame {
 from {
 opacity: .6;
 transform: scaleY(.6) translateY(15%);
 }

 to {
 opacity: 1;
 transform: scaleY(1.25) translateY(-10%) skewX(6deg);
 }
}

.nd-frost .nd-ring {
 background: conic-gradient(var(--nitro-ice), var(--nitro-white), var(--nitro-ice-2), var(--nitro-white), var(--nitro-ice));
 filter: drop-shadow(0 0 5px var(--nitro-ice-2));
 animation: 10s linear infinite reverse nd-spin;
}

.nd-frost i {
 width: 20%;
 height: 20%;
 left: calc(50% + 48% * cos(calc(var(--i) * 60deg + 30deg)) - 10%);
 top: calc(50% + 48% * sin(calc(var(--i) * 60deg + 30deg)) - 10%);
 background: var(--nitro-white);
 clip-path: polygon(45% 0, 55% 0, 55% 40%, 90% 20%, 95% 28%, 60% 50%, 95% 72%, 90% 80%, 55% 60%, 55% 100%, 45% 100%, 45% 60%, 10% 80%, 5% 72%, 40% 50%, 5% 28%, 10% 20%, 45% 40%);
 filter: drop-shadow(0 0 3px var(--nitro-ice-2));
 animation: 6s linear infinite nd-spin;
}

.nd-bloom .nd-ring {
 background: conic-gradient(var(--nitro-pink), var(--nitro-lime), var(--nitro-pink-2), var(--nitro-lime), var(--nitro-pink));
}

.nd-bloom i {
 width: 22%;
 height: 22%;
 left: calc(50% + 49% * cos(calc(var(--i) * 45deg)) - 11%);
 top: calc(50% + 49% * sin(calc(var(--i) * 45deg)) - 11%);
 background: radial-gradient(circle, var(--nitro-gold) 18%, transparent 20%), conic-gradient(from 0deg, var(--nitro-pink) 0 20%, transparent 0 25%, var(--nitro-pink) 0 45%, transparent 0 50%, var(--nitro-pink) 0 70%, transparent 0 75%, var(--nitro-pink) 0 95%, transparent 0);
 animation: 2.6s ease-in-out infinite nd-breathe, 9s linear infinite nd-spin;
 animation-delay: calc(var(--i) * -.3s);
 border-radius: 50%;
}

.nd-aurora .nd-ring {
 background: conic-gradient(var(--nitro-cyan), var(--nitro-violet), var(--nitro-pink), var(--nitro-lime), var(--nitro-cyan));
 filter: blur(.4px) drop-shadow(0 0 8px var(--nitro-violet));
 animation: 4s linear infinite nd-spin;
}

.nd-aurora:after {
 content: "";
 background: conic-gradient(var(--nitro-cyan), var(--nitro-violet), var(--nitro-pink), var(--nitro-lime), var(--nitro-cyan));
 filter: blur(10px);
 opacity: .45;
 z-index: -1;
 border-radius: 9999px;
 animation: 4s linear infinite nd-spin;
 position: absolute;
 inset: 0;
}

.nd-halo .nd-ring {
 background: conic-gradient(var(--nitro-gold), var(--nitro-white), var(--nitro-gold));
 opacity: .55;
}

.nd-halo:before {
 content: "";
 border: 3px solid var(--nitro-gold);
 height: 16%;
 box-shadow: 0 0 10px var(--nitro-gold), inset 0 0 6px var(--nitro-gold);
 border-radius: 50%;
 animation: 2.8s ease-in-out infinite nd-float;
 position: absolute;
 top: -10%;
 left: 18%;
 right: 18%;
}

@keyframes nd-float {
 50% {
 transform: translateY(-12%);
 }
}

.nd-orbit .nd-ring {
 background: var(--nitro-cyan);
 opacity: .35;
 -webkit-mask: radial-gradient(farthest-side, #0000 96%, #000 97% 100%);
 mask: radial-gradient(farthest-side, #0000 96%, #000 97% 100%);
}

.nd-orbit i {
 animation: nd-spin calc(3s + var(--i) * 1.4s) linear infinite;
 animation-delay: calc(var(--i) * -.9s);
 border-radius: 50%;
 inset: 0;
}

.nd-orbit i:before {
 content: "";
 background: radial-gradient(circle at 30% 30%, var(--nitro-white), var(--nitro-cyan) 45%, var(--nitro-violet));
 width: 12%;
 height: 12%;
 box-shadow: 0 0 8px var(--nitro-cyan);
 border-radius: 50%;
 position: absolute;
 top: -4%;
 left: 46%;
}

.nd-orbit i:nth-child(3):before {
 background: radial-gradient(circle at 30% 30%, var(--nitro-white), var(--nitro-fire) 50%, var(--nitro-fire-2));
 box-shadow: 0 0 8px var(--nitro-fire);
}

.nd-orbit i:nth-child(4):before {
 background: var(--nitro-lime);
 width: 8%;
 height: 8%;
 box-shadow: 0 0 8px var(--nitro-lime);
}

.nd-neon .nd-ring {
 background: var(--nitro-pink-2);
 box-shadow: none;
 filter: drop-shadow(0 0 4px var(--nitro-pink-2)) drop-shadow(0 0 10px var(--nitro-pink-2));
 animation: 4s step-end infinite nd-flicker;
}

.nd-neon:after {
 content: "";
 border: 2px solid var(--nitro-cyan);
 filter: drop-shadow(0 0 6px var(--nitro-cyan));
 border-radius: 9999px;
 animation: 5s step-end infinite reverse nd-flicker;
 position: absolute;
 inset: -6%;
}

@keyframes nd-flicker {
 0%, 19%, 22%, 62%, 64%, 100% {
 opacity: 1;
 }

 20%, 63% {
 opacity: .25;
 }
}

.nd-galaxy .nd-ring {
 background: conic-gradient(var(--nitro-violet), oklch(30% .12 280), var(--nitro-cyan), oklch(30% .12 280), var(--nitro-violet));
 filter: drop-shadow(0 0 8px var(--nitro-violet));
 animation: 7s linear infinite nd-spin;
}

.nd-galaxy i {
 background: var(--nitro-white);
 width: 5%;
 height: 5%;
 box-shadow: 0 0 4px var(--nitro-white);
 left: calc(50% + (44% + var(--i) * 0.6%) * cos(calc(var(--i) * 36deg)));
 top: calc(50% + (44% + var(--i) * 0.6%) * sin(calc(var(--i) * 36deg)));
 animation: 1.8s ease-in-out infinite nd-twinkle;
 animation-delay: calc(var(--i) * -.27s);
 border-radius: 50%;
}

.nce {
 pointer-events: none;
 z-index: 20;
 border-radius: inherit;
 position: absolute;
 inset: 0;
 overflow: hidden;
}

.nce i {
 left: var(--x);
 width: calc(8px * var(--s));
 height: calc(8px * var(--s));
 animation: nce-fall var(--t) linear infinite;
 animation-delay: var(--d);
 display: block;
 position: absolute;
 top: -8%;
}

@keyframes nce-fall {
 from {
 transform: translate(0) rotate(0);
 }

 to {
 transform: translate(var(--drift), 115cqh) rotate(540deg);
 }
}

@keyframes nce-rise {
 from {
 opacity: 0;
 transform: translate(0) scale(1);
 }

 10% {
 opacity: 1;
 }

 to {
 transform: translate(var(--drift), -115cqh) scale(.3);
 opacity: 0;
 }
}

@keyframes nce-blink {
 0%, 100% {
 opacity: 0;
 transform: scale(.3) rotate(0);
 }

 50% {
 opacity: 1;
 transform: scale(1) rotate(45deg);
 }
}

.nce {
 container-type: size;
}

.nce-snow i {
 background: var(--nitro-white);
 filter: blur(.6px);
 opacity: .85;
 border-radius: 50%;
}

.nce-embers i, .nce-bubbles i {
 animation-name: nce-rise;
 top: auto;
 bottom: -8%;
}

.nce-embers i {
 width: calc(5px * var(--s));
 height: calc(5px * var(--s));
 background: var(--nitro-fire-3);
 box-shadow: 0 0 6px 2px var(--nitro-fire);
 border-radius: 50%;
}

.nce-bubbles i {
 width: calc(14px * var(--s));
 height: calc(14px * var(--s));
 border: 1.5px solid var(--nitro-cyan);
 border-radius: 50%;
}

@supports (color: color-mix(in lab, red, red)) {
 .nce-bubbles i {
 border: 1.5px solid color-mix(in oklab, var(--nitro-cyan) 80%, transparent);
 }
}

.nce-bubbles i {
 background: radial-gradient(circle at 30% 30%, var(--nitro-white), transparent 40%);
}

@supports (color: color-mix(in lab, red, red)) {
 .nce-bubbles i {
 background: radial-gradient(circle at 30% 30%, color-mix(in oklab, var(--nitro-white) 70%, transparent), transparent 40%);
 }
}

.nce-sparkles i, .nce-stars i {
 top: var(--y);
 animation-name: nce-blink;
 animation-duration: calc(var(--t) / 3);
}

.nce-sparkles i {
 width: calc(14px * var(--s));
 height: calc(14px * var(--s));
 background: var(--nitro-gold);
 clip-path: polygon(50% 0, 61% 39%, 100% 50%, 61% 61%, 50% 100%, 39% 61%, 0 50%, 39% 39%);
 filter: drop-shadow(0 0 4px var(--nitro-gold));
}

.nce-stars i {
 width: calc(3px * var(--s) + 1px);
 height: calc(3px * var(--s) + 1px);
 background: var(--nitro-white);
 box-shadow: 0 0 5px var(--nitro-white);
 border-radius: 50%;
}

.nce-stars:before {
 content: "";
 background: radial-gradient(ellipse at 30% 0%, var(--nitro-violet), transparent 60%);
 position: absolute;
 inset: 0;
}

@supports (color: color-mix(in lab, red, red)) {
 .nce-stars:before {
 background: radial-gradient(ellipse at 30% 0%, color-mix(in oklab, var(--nitro-violet) 35%, transparent), transparent 60%);
 }
}

.nce-petals i {
 width: calc(12px * var(--s));
 height: calc(8px * var(--s));
 background: linear-gradient(135deg, var(--nitro-pink), var(--nitro-pink-2));
 opacity: .9;
 border-radius: 100% 0;
}

.nce-hearts i {
 width: calc(14px * var(--s));
 height: calc(13px * var(--s));
 background: var(--nitro-pink-2);
 clip-path: path("M7 13 L1.2 7.2 A3.4 3.4 0 0 1 7 2.4 A3.4 3.4 0 0 1 12.8 7.2 Z");
 filter: drop-shadow(0 0 4px var(--nitro-pink));
 animation-name: nce-rise;
 top: auto;
 bottom: -8%;
}

.nce-confetti i {
 width: calc(6px * var(--s));
 height: calc(10px * var(--s));
 background: oklch(.78 .18 var(--h));
 border-radius: 1px;
}

.nitro-name {
 -webkit-text-fill-color: transparent;
 background-size: 200%;
 -webkit-background-clip: text;
 background-clip: text;
 animation: 4s linear infinite nitro-name-pan;
 color: #0000 !important;
}

@keyframes nitro-name-pan {
 to {
 background-position: 200%;
 }
}

.nitro-name-aurora {
 background-image: linear-gradient(90deg, var(--nitro-cyan), var(--nitro-violet), var(--nitro-pink), var(--nitro-cyan));
}

.nitro-name-gold {
 background-image: linear-gradient(90deg, var(--nitro-gold-2), var(--nitro-gold), var(--nitro-white), var(--nitro-gold), var(--nitro-gold-2));
 filter: drop-shadow(0 0 6px var(--nitro-gold));
}

@supports (color: color-mix(in lab, red, red)) {
 .nitro-name-gold {
 filter: drop-shadow(0 0 6px color-mix(in oklab, var(--nitro-gold) 45%, transparent));
 }
}

.nitro-name-neon {
 background-image: linear-gradient(90deg, var(--nitro-pink-2), var(--nitro-cyan), var(--nitro-pink-2));
 filter: drop-shadow(0 0 5px var(--nitro-pink-2));
}

.nitro-name-fire {
 background-image: linear-gradient(90deg, var(--nitro-fire-2), var(--nitro-fire), var(--nitro-fire-3), var(--nitro-fire), var(--nitro-fire-2));
 animation-duration: 1.8s;
}

.nitro-name-ice {
 background-image: linear-gradient(90deg, var(--nitro-ice-2), var(--nitro-white), var(--nitro-ice), var(--nitro-ice-2));
}

.nitro-name-rainbow {
 background-image: linear-gradient(90deg, oklch(75% .2 25), oklch(85% .18 90), oklch(80% .2 145), oklch(75% .15 230), oklch(70% .2 300), oklch(75% .2 25));
 animation-duration: 3s;
}

@media (prefers-reduced-motion: reduce) {
 .nd, .nd *, .nd:before, .nd:after, .nce i, .nitro-name {
 animation: none !important;
 }
}

.nd-halo {
 perspective: 120px;
}

.nd-halo:before {
 background: conic-gradient(from 0deg, transparent, var(--nitro-white), transparent 30%);
 animation: 2.8s ease-in-out infinite nd-float, 2.2s linear infinite nd-halo-spin;
}

@supports (color: color-mix(in lab, red, red)) {
 .nd-halo:before {
 background: conic-gradient(from 0deg, transparent, color-mix(in oklab, var(--nitro-white) 70%, transparent), transparent 30%);
 }
}

@keyframes nd-halo-spin {
 to {
 rotate: y 1turn;
 }
}

.nd-crown .nd-ring {
 background: conic-gradient(var(--nitro-gold), var(--nitro-gold-2), var(--nitro-white), var(--nitro-gold));
 filter: drop-shadow(0 0 6px var(--nitro-gold));
 animation: 5s linear infinite nd-spin;
}

.nd-crown i {
 background: linear-gradient(var(--nitro-gold), var(--nitro-gold-2));
 clip-path: polygon(0 100%, 0 30%, 20% 60%, 35% 0, 50% 55%, 65% 0, 80% 60%, 100% 30%, 100% 100%);
 width: 44%;
 height: 26%;
 filter: drop-shadow(0 0 5px var(--nitro-gold));
 animation: 2.6s ease-in-out infinite nd-float;
 top: -22%;
 left: 28%;
}

.nd-storm .nd-ring {
 background: conic-gradient(oklch(45% .05 260), var(--nitro-cyan), oklch(45% .05 260), var(--nitro-white), oklch(45% .05 260));
 animation: 2.5s linear infinite nd-spin;
}

.nd-storm i {
 width: 18%;
 height: 30%;
 left: calc(15% + var(--i) * 30%);
 background: var(--nitro-cyan);
 clip-path: polygon(40% 0, 100% 0, 60% 40%, 90% 40%, 20% 100%, 40% 55%, 10% 55%);
 filter: drop-shadow(0 0 6px var(--nitro-cyan));
 animation: 1.4s step-end infinite nd-flicker;
 animation-delay: calc(var(--i) * -.45s);
 top: -10%;
}

.nd-lovestruck .nd-ring {
 background: conic-gradient(var(--nitro-pink), var(--nitro-pink-2), var(--nitro-pink));
}

.nd-lovestruck i {
 animation: 5s linear infinite nd-spin;
 animation-delay: calc(var(--i) * -.83s);
 inset: 0;
}

.nd-lovestruck i:before {
 content: "";
 background: var(--nitro-pink-2);
 width: 15%;
 height: 14%;
 clip-path: path("M7 13 L1.2 7.2 A3.4 3.4 0 0 1 7 2.4 A3.4 3.4 0 0 1 12.8 7.2 Z");
 transform: scale(calc(var(--s, 1)));
 filter: drop-shadow(0 0 3px var(--nitro-pink));
 position: absolute;
 top: -6%;
 left: 43%;
}

.nd-sunset .nd-ring {
 filter: drop-shadow(0 0 7px oklch(70% .2 30));
 background: conic-gradient(oklch(70% .2 30), oklch(82% .16 70), oklch(60% .2 350), oklch(50% .18 300), oklch(70% .2 30));
 animation: 6s linear infinite nd-spin;
}

.nd-toxic .nd-ring {
 background: conic-gradient(var(--nitro-lime), oklch(50% .15 150), var(--nitro-lime));
 filter: drop-shadow(0 0 8px var(--nitro-lime));
 animation: 3s linear infinite nd-spin;
}

.nd-toxic i {
 bottom: 0;
 left: calc(12% + var(--i) * 18%);
 background: var(--nitro-lime);
 width: 10%;
 height: 10%;
 box-shadow: 0 0 6px var(--nitro-lime);
 animation: 2s ease-in infinite nd-bubble;
 animation-delay: calc(var(--i) * -.4s);
 border-radius: 50%;
}

@keyframes nd-bubble {
 from {
 opacity: 1;
 transform: translateY(0) scale(.6);
 }

 to {
 opacity: 0;
 transform: translateY(-120%) scale(1.2);
 }
}

.nd-rose .nd-ring {
 filter: drop-shadow(0 0 5px oklch(82% .08 30));
 background: conic-gradient(oklch(82% .08 30), oklch(95% .03 60), oklch(70% .1 20), oklch(95% .03 60), oklch(82% .08 30));
 animation: 9s linear infinite nd-spin;
}

.nce-lightning i {
 top: 0;
 left: var(--x);
 background: var(--nitro-cyan);
 clip-path: polygon(40% 0, 70% 0, 52% 38%, 75% 38%, 25% 100%, 40% 52%, 20% 52%);
 width: 26%;
 height: 70%;
 filter: drop-shadow(0 0 8px var(--nitro-cyan));
 animation: nce-strike var(--t) steps(1) infinite;
 animation-delay: var(--d);
}

.nce-lightning:before {
 content: "";
 background: var(--nitro-cyan);
 opacity: 0;
 animation: 5s step-end infinite nce-flash;
 position: absolute;
 inset: 0;
}

@keyframes nce-strike {
 0%, 14% {
 opacity: 1;
 }

 15%, 100% {
 opacity: .15;
 }
}

@keyframes nce-flash {
 0%, 2% {
 opacity: .18;
 }

 3%, 100% {
 opacity: 0;
 }
}

.nce-leaves i {
 width: calc(14px * var(--s));
 height: calc(10px * var(--s));
 background: linear-gradient(135deg, oklch(75% .17 60), oklch(60% .2 35));
 border-radius: 0 100%;
}

.nce-fireflies i {
 top: var(--y);
 width: 5px;
 height: 5px;
 animation: nce-wander var(--t) ease-in-out infinite alternate, nce-blink calc(var(--t) / 2) ease-in-out infinite;
 animation-delay: var(--d);
 background: oklch(92% .18 110);
 border-radius: 50%;
 box-shadow: 0 0 8px 2px oklch(90% .2 110);
}

@keyframes nce-wander {
 to {
 translate: var(--drift) calc(var(--drift) * -1);
 }
}

.nce-matrix i {
 width: auto;
 height: auto;
 font: 700 calc(10px * var(--s) + 4px) / 1 monospace;
 color: var(--nitro-lime);
 text-shadow: 0 0 6px var(--nitro-lime);
 writing-mode: vertical-rl;
 opacity: .8;
}

.nce-matrix i:before {
 content: "TATO01SPUD";
}

.nce-matrix i {
 animation-name: nce-drop;
}

@keyframes nce-drop {
 from {
 transform: translateY(-40%);
 }

 to {
 transform: translateY(115cqh);
 }
}

.nce-aurora i {
 top: 0;
 left: calc(var(--x) - 30%);
 background: radial-gradient(ellipse, oklch(.8 .17 calc(150 + var(--h) / 3)), transparent 70%);
 border-radius: 50%;
 width: 80%;
 height: 60%;
}

@supports (color: color-mix(in lab, red, red)) {
 .nce-aurora i {
 background: radial-gradient(ellipse, color-mix(in oklab, oklch(.8 .17 calc(150 + var(--h) / 3)) 55%, transparent), transparent 70%);
 }
}

.nce-aurora i {
 filter: blur(14px);
 animation: nce-sway var(--t) ease-in-out infinite alternate;
 animation-delay: var(--d);
}

@keyframes nce-sway {
 from {
 transform: translateX(-20%) scaleY(.8);
 }

 to {
 transform: translateX(25%) scaleY(1.2);
 }
}

.nitro-name-sunset {
 background-image: linear-gradient(90deg, oklch(70% .2 30), oklch(85% .15 75), oklch(65% .22 350), oklch(70% .2 30));
}

.nitro-name-toxic {
 background-image: linear-gradient(90deg, var(--nitro-lime), oklch(95% .2 120), oklch(60% .18 150), var(--nitro-lime));
 filter: drop-shadow(0 0 5px var(--nitro-lime));
}

@supports (color: color-mix(in lab, red, red)) {
 .nitro-name-toxic {
 filter: drop-shadow(0 0 5px color-mix(in oklab, var(--nitro-lime) 50%, transparent));
 }
}

.nitro-name-chrome {
 background-image: linear-gradient(90deg, oklch(60% 0 0), var(--nitro-white), oklch(50% .02 250), var(--nitro-white), oklch(60% 0 0));
 animation-duration: 2.5s;
}

.nitro-name-galaxy {
 background-image: linear-gradient(90deg, var(--nitro-violet), var(--nitro-cyan), oklch(60% .25 320), var(--nitro-violet));
 filter: drop-shadow(0 0 5px var(--nitro-violet));
}

:root {
 --panel: var(--card);
 --panel-2: var(--muted);
 --line: var(--border);
 --glass-surface: var(--card);
 --glass-border: var(--border);
}

.aero-page-outlet {
 flex-direction: column;
 display: flex;
 position: relative;
}

.aero-page-outlet > * {
 flex: none;
 min-width: 0;
}

.aero-page-outlet > .h-full {
 flex: 1;
 height: 0;
 min-height: 0;
}

.aero-page-outlet > .min-h-full {
 min-height: 100%;
}

@media (width <= 767px) {
 .aero-app-shell > aside {
 z-index: 40;
 max-width: min(204px, 85vw);
 box-shadow: var(--shadow-panel);
 position: absolute;
 inset: 0 auto 0 0;
 }
}

.aero-browser-start {
 flex-direction: column;
 align-items: center;
 min-height: 100%;
 padding: 2rem 1rem;
 display: flex;
}

.aero-browser-start h1 {
 font-size: 2rem;
}

.aero-browser-start form {
 width: min(100%, 40rem);
}

.aero-browser-start > div {
 width: min(100%, 60rem);
}

.aero-bg-glow {
 display: none;
}

* {
 letter-spacing: 0;
}

.aero-profile-halo:after, .aero-profile-sparkle:after, .aero-profile-frost:after, .aero-profile-pulse:after, .aero-profile-orbit:after {
 content: "";
 pointer-events: none;
 border: 2px solid var(--primary);
 border-radius: 50%;
 position: absolute;
 inset: -5px;
}

.aero-profile-halo:after {
 border-top-color: var(--foreground);
 border-bottom-color: #0000;
 animation: 6s linear infinite aero-avatar-spin;
}

.aero-profile-sparkle:after {
 border-style: dotted;
 border-color: var(--foreground);
 animation: 18s linear infinite aero-avatar-spin;
}

.aero-profile-frost:after {
 border-color: var(--soft-foreground);
 box-shadow: 0 0 12px var(--primary);
}

.aero-profile-pulse:after {
 animation: 2s ease-in-out infinite aero-avatar-pulse;
}

.aero-profile-orbit:after {
 border-style: dashed;
 animation: 12s linear infinite reverse aero-avatar-spin;
}

.aero-name-glow {
 color: var(--primary);
 text-shadow: 0 0 8px var(--primary);
}

.aero-name-rainbow {
 color: var(--primary);
 background: linear-gradient(90deg,var(--primary),var(--success),var(--destructive));
 -webkit-text-fill-color: transparent;
 -webkit-background-clip: text;
 background-clip: text;
}

@keyframes aero-avatar-spin {
 to {
 transform: rotate(360deg);
 }
}

@keyframes aero-avatar-pulse {
 50% {
 opacity: .4;
 transform: scale(1.12);
 }
}

@media (prefers-reduced-motion: reduce) {
 [class*="aero-profile-"]:after {
 animation: none;
 }
}

[data-motion="off"] [class*="aero-profile-"]:after {
 animation: none;
}

