 }
 @keyframes edge-animation-frame {
 from {
 stroke-dashoffset: 0;
 }
 }
 @keyframes dash {
 to {
 stroke-dashoffset: 0;
 }
 }
 & .edge-animation-slow {
 stroke-dasharray: 9,5 !important;
 stroke-dashoffset: 900;
 animation: dash 50s linear infinite;
 stroke-linecap: round;
 }
 & .edge-animation-fast {
 stroke-dasharray: 9,5 !important;
 stroke-dashoffset: 900;
 animation: dash 20s linear infinite;
 stroke-linecap: round;
 }
 /* Classes common for multiple diagrams */

 & .error-icon {
 fill: ${n.errorBkgColor};
 }
 & .error-text {
 fill: ${n.errorTextColor};
 stroke: ${n.errorTextColor};
 }

 & .edge-thickness-normal {
 stroke-width: ${n.strokeWidth??1}px;
 }
 & .edge-thickness-thick {
 stroke-width: 3.5px
 }
 & .edge-pattern-solid {
 stroke-dasharray: 0;
 }
 & .edge-thickness-invisible {
 stroke-width: 0;
 fill: none;
 }
 & .edge-pattern-dashed{
 stroke-dasharray: 3;
 }
 .edge-pattern-dotted {
 stroke-dasharray: 2;
 }

 & .marker {
 fill: ${n.lineColor};
 stroke: ${n.lineColor};
 }
 & .marker.cross {
 stroke: ${n.lineColor};
 }

 & svg {
 font-family: ${n.fontFamily};
 font-size: ${n.fontSize};
 }
 & p {
 margin: 0
 }

 ${r}
 .node .neo-node {
 stroke: ${n.nodeBorder};
 }

 [data-look="neo"].node rect, [data-look="neo"].cluster rect, [data-look="neo"].node polygon {
 stroke: ${n.useGradient?"url("+a+"-gradient)":n.nodeBorder};
 filter: ${n.dropShadow?n.dropShadow.replace("url(#drop-shadow)",`url(${a}-drop-shadow)`):"none"};
 }
 [data-look="neo"].swimlane.cluster rect {
 filter: none;
 }


 [data-look="neo"].node path {
 stroke: ${n.useGradient?"url("+a+"-gradient)":n.nodeBorder};
 stroke-width: ${n.strokeWidth??1}px;
 }

 [data-look="neo"].node .outer-path {
 filter: ${n.dropShadow?n.dropShadow.replace("url(#drop-shadow)",`url(${a}-drop-shadow)`):"none"};
 }

 [data-look="neo"].node .neo-line path {
 stroke: ${n.nodeBorder};
 filter: none;
 }

 [data-look="neo"].node circle{
 stroke: ${n.useGradient?"url("+a+"-gradient)":n.nodeBorder};
 filter: ${n.dropShadow?n.dropShadow.replace("url(#drop-shadow)",`url(${a}-drop-shadow)`):"none"};
 }

 [data-look="neo"].node circle .state-start{
 fill: #000000;
 }

 [data-look="neo"].icon-shape .icon {
 fill: ${n.useGradient?"url("+a+"-gradient)":n.nodeBorder};
 filter: ${n.dropShadow?n.dropShadow.replace("url(#drop-shadow)",`url(${a}-drop-shadow)`):"none"};
 }

 [data-look="neo"].icon-shape .icon-neo path {
 stroke: ${n.useGradient?"url("+a+"-gradient)":n.nodeBorder};
 filter: ${n.dropShadow?n.dropShadow.replace("url(#drop-shadow)",`url(${a}-drop-shadow)`):"none"};
