 .fd-root{position:fixed;inset:0;z-index:999;background:#202124;overflow:hidden;font-family:Roboto,Arial,sans-serif;user-select:text}
 .fd-exit{position:fixed;right:10px;bottom:10px;z-index:1000;width:26px;height:26px;border-radius:50%;border:1px solid rgba(255,255,255,.18);background:rgba(0,0,0,.35);color:rgba(255,255,255,.25);font-size:12px;line-height:1;opacity:0;transition:opacity .15s}
 .fd-root:hover .fd-exit{opacity:1}
 .fd-docs{display:flex;flex-direction:column;height:100%;background:#303133;color:#e8eaed}
 .fd-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 14px}
 .fd-bar-left{display:flex;align-items:center;gap:8px;min-width:0}
 .fd-orb{width:18px;height:18px;border-radius:50%;background:#1a73e8;flex:none}
 .fd-name{font-size:14px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
 .fd-star{color:#f1c40f;font-size:14px}
 .fd-saved{font-size:11px;color:#9aa0a6;margin-left:6px}
 .fd-bar-right{display:flex;align-items:center;gap:10px;flex:none}
 .fd-avatar{width:26px;height:26px;border-radius:50%;background:#7b8a9a;color:#fff;display:grid;place-items:center;font-size:12px}
 .fd-share{border:1px solid #8ab4f8;color:#8ab4f8;border-radius:4px;padding:5px 14px;font-size:13px}
 .fd-dots{font-size:18px;color:#9aa0a6}
 .fd-menus{display:flex;gap:16px;padding:2px 14px 8px;font-size:12px;color:#bdc1c6}
 .fd-tools{display:flex;gap:14px;align-items:center;padding:6px 14px;border-top:1px solid #3c4043;border-bottom:1px solid #3c4043;font-size:12px;color:#9aa0a6}
 .fd-page{flex:1;overflow:auto;display:flex;justify-content:center;padding:26px 16px}
 .fd-body{width:min(720px,100%);background:#202124;color:#e8eaed;padding:44px 56px;outline:none;font-size:14px;line-height:1.7}
 .fd-title{font-size:20px;font-weight:600;margin:0 0 18px}
 .fd-h{font-weight:600;margin:18px 0 6px}
 .fd-body p{margin:0 0 10px;white-space:pre-wrap}
 .fd-caret span{display:inline-block;width:1px;height:16px;background:#8ab4f8;vertical-align:-3px;animation:fdblink 1s steps(1) infinite}
 @keyframes fdblink{50%{opacity:0}}
 .fd-foot{display:flex;justify-content:space-between;padding:6px 16px;font-size:11px;color:#9aa0a6;border-top:1px solid #3c4043}
 .fd-canvas{display:flex;height:100%;background:#f6f7f9;color:#2d3b45}
 .fd-side{width:220px;flex:none;background:#2d3b45;padding:14px 0}
 .fd-brand{color:#fff;font-weight:600;padding:0 18px 14px;font-size:15px}
 .fd-side nav{display:flex;flex-direction:column}
 .fd-side nav span{padding:9px 18px;font-size:13px;color:#cfd6dd;cursor:default}
 .fd-side nav .fd-active{background:#1c3b5e;color:#fff}
 .fd-main{flex:1;min-width:0;overflow:auto;padding:18px 24px}
 .fd-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d7dce2;padding-bottom:10px;margin-bottom:16px}
 .fd-course{font-size:17px;font-weight:600}
 .fd-home{font-size:13px;color:#0374b5}
 .fd-cols{display:grid;grid-template-columns:1fr 1fr;gap:16px}
 .fd-card{background:#fff;border:1px solid #d7dce2;border-radius:6px;padding:14px 16px}
 .fd-card h2{font-size:14px;font-weight:600;margin:0 0 10px}
 .fd-item{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid #eaedf0;font-size:13px}
 .fd-item-name{color:#0374b5}
 .fd-item-due{color:#6b7785;font-size:12px;white-space:nowrap}
 .fd-empty{font-size:12px;color:#8b95a1;padding:10px 0}
 .fd-post{font-size:13px;line-height:1.6;color:#3d4852;margin:0 0 12px}
 @media (max-width:700px){.fd-side{display:none}.fd-cols{grid-template-columns:1fr}.fd-body{padding:24px 20px}}
